(6438360, 955786, 18778, '<td valign="top">I like the lines of this image- my eye is drawn from the asymmetrical lines of the wand down to the centered jar.  The color of the honey is rich &amp; I like how the jar is ''used''.</td>', 'I like the lines of this image- my eye is drawn from the asymmetrical lines of the wand down to the centered jar.  The color of the honey is rich & I like how the jar is ''used''.', '2011-06-08 11:35:45.000000', NULL, 1),
(6438364, 955376, 49916, '<td valign="top">Not related to honey :-(</td>', 'Not related to honey :-(', '2011-06-08 11:39:35.000000', NULL, 1),
(6438369, 955951, 18778, '<td valign="top">I find this to be beautiful- I love the softness of the petals in contrast with the various textures of the bee while still having a warm monochromatic look.  Howeves- not sure it''s in line with the challenge?</td>', 'I find this to be beautiful- I love the softness of the petals in contrast with the various textures of the bee while still having a warm monochromatic look.  Howeves- not sure it''s in line with the challenge?', '2011-06-08 11:40:54.000000', NULL, 1),
(6438370, 955769, 132967, '<td valign="top">Pretty picture and different perspective on honey, but it just didn''t seem very sharp on the focus.</td>', 'Pretty picture and different perspective on honey, but it just didn''t seem very sharp on the focus.', '2011-06-08 11:41:14.000000', NULL, 1),
(6438372, 955967, 132967, '<td valign="top">I liked how this was different, but the focus seems a bit off.</td>', 'I liked how this was different, but the focus seems a bit off.', '2011-06-08 11:42:28.000000', NULL, 1),
(6438373, 955860, 132967, '<td valign="top">Very peaceful and soft, but didn''t seem very focused.  I would have liked a little sharper focus on the bee to capture some of its detail.</td>', 'Very peaceful and soft, but didn''t seem very focused.  I would have liked a little sharper focus on the bee to capture some of its detail.', '2011-06-08 11:43:11.000000', NULL, 1),
(6438379, 954944, 132967, '<td valign="top">Pretty flowers, but it would have been a lot more interesting if you had been able to zoom in on the bee more.</td>', 'Pretty flowers, but it would have been a lot more interesting if you had been able to zoom in on the bee more.', '2011-06-08 11:45:41.000000', NULL, 1),
(6438380, 955917, 132967, '<td valign="top">Interesting composition.</td>', 'Interesting composition.', '2011-06-08 11:46:13.000000', NULL, 1),
(6438381, 955381, 132967, '<td valign="top">I like the different perspective, but I wish you could have focused on the bee more.</td>', 'I like the different perspective, but I wish you could have focused on the bee more.', '2011-06-08 11:46:49.000000', NULL, 1),
(6438382, 955895, 132967, '<td valign="top">Beautiful flowers and lighting, but just didn''t seem to fit with the theme of this challenge.</td>', 'Beautiful flowers and lighting, but just didn''t seem to fit with the theme of this challenge.', '2011-06-08 11:47:36.000000', NULL, 1),
(6438384, 955651, 132967, '<td valign="top">It''s hard to get a good squirrel picture, but it seemed to take away from the bee boxes.</td>', 'It''s hard to get a good squirrel picture, but it seemed to take away from the bee boxes.', '2011-06-08 11:48:11.000000', NULL, 1),
(6438385, 954854, 132967, '<td valign="top">Interesting composition.  Didn''t seem to fit with the "honey" theme though.</td>', 'Interesting composition.  Didn''t seem to fit with the "honey" theme though.', '2011-06-08 11:48:57.000000', NULL, 1),
(6438394, 955976, 18778, '<td valign="top">The lighting here is...distracting. Although I do appreciate the parallel coloring of the black background &amp; yellow fiesta plate with the coloring of the bee.  Overall- I''m not sure what thought this image is supposed to provoke- &amp; the bee looks less than alive :(</td>', 'The lighting here is...distracting. Although I do appreciate the parallel coloring of the black background & yellow fiesta plate with the coloring of the bee.  Overall- I''m not sure what thought this image is supposed to provoke- & the bee looks less than alive :(', '2011-06-08 11:56:08.000000', NULL, 1),
(6438398, 955953, 132967, '<td valign="top">I appreciate your creativity, but I do not condone nudity in any way, form, or fashion.</td>', 'I appreciate your creativity, but I do not condone nudity in any way, form, or fashion.', '2011-06-08 11:58:38.000000', NULL, 1),
(6438410, 955315, 132967, '<td valign="top">Beautiful colors!  The copyright in the corner ruined it for me though.  Not sure that that is legal however.</td>', 'Beautiful colors!  The copyright in the corner ruined it for me though.  Not sure that that is legal however.', '2011-06-08 12:02:55.000000', NULL, 1),
