(6441460, 955957, 132967, '<td valign="top">Love the bright colors!</td>', 'Love the bright colors!', '2011-06-11 20:14:23.000000', NULL, 1),
(6441461, 955909, 132967, '<td valign="top">It''s a very happy, "Good Morning" type of picture!</td>', 'It''s a very happy, "Good Morning" type of picture!', '2011-06-11 20:14:29.000000', NULL, 1),
(6441462, 955919, 132967, '<td valign="top">Very happy-looking picture!  Just wish the bee was facing a different way.  I know, can''t tell bees what to do!  ;-)</td>', 'Very happy-looking picture!  Just wish the bee was facing a different way.  I know, can''t tell bees what to do!  ;-)', '2011-06-11 20:14:31.000000', NULL, 1),
