(6441466, 955317, 132967, '<td valign="top">Very interesting picture.  I love how you were able to capture the pollen all over the bee''s body.  However, the focus seems to be a bit off.</td>', 'Very interesting picture.  I love how you were able to capture the pollen all over the bee''s body.  However, the focus seems to be a bit off.', '2011-06-11 20:14:47.000000', NULL, 1),
(6441467, 955390, 132967, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2011-06-11 20:14:58.000000', NULL, 1),
(6441468, 955316, 132967, '<td valign="top">Very pure-looking picture.  I like that you captured the gold of the honey.</td>', 'Very pure-looking picture.  I like that you captured the gold of the honey.', '2011-06-11 20:15:02.000000', NULL, 1),
(6441469, 955768, 132967, '<td valign="top">Like the different perspective!</td>', 'Like the different perspective!', '2011-06-11 20:15:05.000000', NULL, 1),
