INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6441474, 955848, 132967, '<td valign="top">Like the almost over-exposed look to this picture.  However, your title ruined it for me...double :, should have been "Pooh''s"...sorry.  I''m a proper English nut.  Neat picture however!</td>', 'Like the almost over-exposed look to this picture.  However, your title ruined it for me...double :, should have been "Pooh''s"...sorry.  I''m a proper English nut.  Neat picture however!', '2011-06-11 20:15:44.000000', NULL, 1),
(6441476, 955976, 132967, '<td valign="top">Interesting picture!  I wish you could have gotten more bee detail, but neat nonetheless!</td>', 'Interesting picture!  I wish you could have gotten more bee detail, but neat nonetheless!', '2011-06-11 20:15:54.000000', NULL, 1),
(6441477, 955296, 132967, '<td valign="top">Neat idea for a picture.  However, the focus seems off to me.  I would have rather had the focus on either the bees or the honey, not the wood frame in the middle.</td>', 'Neat idea for a picture.  However, the focus seems off to me.  I would have rather had the focus on either the bees or the honey, not the wood frame in the middle.', '2011-06-11 20:16:01.000000', NULL, 1),
(6441478, 955904, 132967, '<td valign="top">Beautiful!  I love how you were able to get the wing veins and the fuzziness of the bee!  Good contrasting colors!</td>', 'Beautiful!  I love how you were able to get the wing veins and the fuzziness of the bee!  Good contrasting colors!', '2011-06-11 20:16:05.000000', NULL, 1),
(6441479, 955975, 132967, '<td valign="top">Very interesting!  Like the blurry bees in the background.</td>', 'Very interesting!  Like the blurry bees in the background.', '2011-06-11 20:16:09.000000', NULL, 1),
(6441480, 955460, 132967, '<td valign="top">Great in-flight capture!  I know it''s difficult, but it would have been neat to see the wings better.</td>', 'Great in-flight capture!  I know it''s difficult, but it would have been neat to see the wings better.', '2011-06-11 20:16:16.000000', NULL, 1),
(6441481, 954902, 132967, '<td valign="top">I like the different perspective.  The bear''s red eyebrows almost makes him look mad!  It just didn''t have a very sharp focus for me.</td>', 'I like the different perspective.  The bear''s red eyebrows almost makes him look mad!  It just didn''t have a very sharp focus for me.', '2011-06-11 20:16:19.000000', NULL, 1),
(6441482, 955525, 132967, '<td valign="top">Beautiful flower.  I wish the bee had been in focus too.  It looked like an interesting bee with the pollen sacks.</td>', 'Beautiful flower.  I wish the bee had been in focus too.  It looked like an interesting bee with the pollen sacks.', '2011-06-11 20:16:54.000000', NULL, 1),
(6441483, 955881, 132967, '<td valign="top">Beautiful colors and detail.  However, I was a bit put off by the title.</td>', 'Beautiful colors and detail.  However, I was a bit put off by the title.', '2011-06-11 20:17:09.000000', NULL, 1),
(6441484, 955912, 132967, '<td valign="top">I liked that you used a different kind of honey vs. everyone else.  I like the falling of the spoon.</td>', 'I liked that you used a different kind of honey vs. everyone else.  I like the falling of the spoon.', '2011-06-11 20:17:32.000000', NULL, 1),
(6441486, 955833, 132967, '<td valign="top">Cute dog, but I didn''t think that it really fit with the honey theme.</td>', 'Cute dog, but I didn''t think that it really fit with the honey theme.', '2011-06-11 20:17:36.000000', NULL, 1),
(6441487, 955760, 132967, '<td valign="top">I like how you did something different with honey.</td>', 'I like how you did something different with honey.', '2011-06-11 20:17:41.000000', NULL, 1),
