INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6444054, 955765, 62006, '<td valign="top">Congrats on an superb entry. I gave it a 10 and hoped it would be the blue. This is why I came back to DPC.</td>', 'Congrats on an superb entry. I gave it a 10 and hoped it would be the blue. This is why I came back to DPC.', '2011-06-15 01:11:31.000000', NULL, 0),
(6444056, 955765, 60862, '<td valign="top">Congrats!  Thanks for sharing the story.<br/> <br/>You actually were a great photojournalist for this challenge - you thought how to tell the story visually, did your research, and landed a terrific photo. :)<br/> <br/>Way to go, also, on getting your new 2nd-best score ever.  Quite a tricky feat given your high-scoring record!</td>', 'Congrats!  Thanks for sharing the story. You actually were a great photojournalist for this challenge - you thought how to tell the story visually, did your research, and landed a terrific photo. :) Way to go, also, on getting your new 2nd-best score ever.  Quite a tricky feat given your high-scoring record!', '2011-06-15 01:11:37.000000', NULL, 0),
(6444057, 955751, 30982, '<td valign="top">This is fascinating!!  Excellent photo - congrats on the ribbon!</td>', 'This is fascinating!!  Excellent photo - congrats on the ribbon!', '2011-06-15 01:12:09.000000', NULL, 0),
(6444058, 955953, 83313, '<td valign="top">Hmm, NOT Leroy! My only 10 in the challenge. Again, well done.</td>', 'Hmm, NOT Leroy! My only 10 in the challenge. Again, well done.', '2011-06-15 01:12:21.000000', NULL, 0),
(6444059, 955953, 83233, '<td valign="top">Thank you for  comments . I sure had fun taking this shot :)</td>', 'Thank you for  comments . I sure had fun taking this shot :)', '2011-06-15 01:13:31.000000', NULL, 0),
